def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    strong_prev = 0
    weak_prev = 0
    urgent_opp = 0

    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opps.append(opp)
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                b = float(bid)
                prev_bids.append(b)
                if b >= 100:
                    strong_prev += 1
                if b <= 60:
                    weak_prev += 1

    if budget <= 0:
        return 0.0

    slots = supply / WATER_REQ
    if slots >= 1.9:
        base = 18.0
    elif slots >= 1.4:
        base = 28.0
    else:
        base = 40.0

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
        if highest_prev >= 150:
            base = min(base, 34.0)
        elif avg_prev >= 100:
            base = max(base, 32.0)
        elif highest_prev <= 60:
            base = max(base, 30.0)
    else:
        highest_prev = 0.0

    if len(alive_opps) <= 1:
        base = min(base, 24.0)

    if hp <= 2 or no_water >= 2:
        base = max(base, 92.0)
    elif hp <= 4 or no_water >= 1:
        base = max(base, 62.0)

    if urgent_opp >= 2 and hp > 4 and no_water == 0:
        base = min(base, 26.0)

    if day >= 8:
        base += 8.0
    if day >= 9 and (hp <= 4 or no_water >= 1):
        base += 18.0

    if budget < 50:
        base = min(base, budget)
    elif budget > 180 and hp <= 4:
        base += 10.0

    bid = min(float(budget), max(0.0, base))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    base_bid = DAILY_SALARY * 0.75

    if my_status['hp'] <= 1:
        base_bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 3:
        base_bid = DAILY_SALARY * 0.85
    elif my_status['hp'] >= 7:
        base_bid = DAILY_SALARY * 0.65

    highest_prev_bid = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])

    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.7:
            if my_status['hp'] <= 3:
                base_bid = max(base_bid, highest_prev_bid + 5)
            else:
                base_bid = max(base_bid, highest_prev_bid + 1)
        else:
            base_bid = max(base_bid, highest_prev_bid + 1)

    estimated_total_demand = WATER_REQ * (num_alive_opponents + 1)

    if day_context['supply'] < estimated_total_demand:
        base_bid *= 1.1
    elif day_context['supply'] > estimated_total_demand * 1.5:
        if my_status['hp'] >= 7:
            base_bid *= 0.9

    remaining_days = EPISODE_DAYS - day_context['day']
    if remaining_days <= 3 and my_status['hp'] <= 5:
        base_bid = DAILY_SALARY * 0.98

    final_bid = min(my_status['budget'], base_bid)
    final_bid = min(final_bid, DAILY_SALARY * 1.05)
    final_bid = max(1.0, final_bid)

    return final_bid

