    max_yesterday_bid = 0.0
    for opp in alive_opponents.values():
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            if prev['bid'] > max_yesterday_bid:
                max_yesterday_bid = prev['bid']
    hp = my_status['hp']
    budget = my_status['budget']
    if hp <= 2:
        target = DAILY_SALARY * 0.85
        if max_yesterday_bid > 0:
            target = max(target, max_yesterday_bid + 0.5)
        return min(budget, target)
    else:
        if max_yesterday_bid > 0:
            target = max(DAILY_SALARY * 0.4, max_yesterday_bid + 1.0)
        else:
            target = DAILY_SALARY * 0.5
        return min(budget, target)
